-- GST/BAS preparation uses immutable source attribution, independently reconstructed tax GL and frozen return revisions.
CREATE TABLE accounting.bas_periods(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),from_date date NOT NULL,to_date date NOT NULL,cadence text NOT NULL CHECK(cadence IN('MONTHLY','QUARTERLY','ANNUAL','CUSTOM')),gst_basis text NOT NULL CHECK(gst_basis IN('CASH','NON_CASH')),reporting_method text NOT NULL CHECK(reporting_method='SIMPLER'),registration_confirmed boolean NOT NULL CHECK(registration_confirmed),due_on date,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,reference),CHECK(to_date>from_date AND to_date-from_date<=366),CHECK(due_on IS NULL OR due_on>=to_date),EXCLUDE USING gist(company_id WITH =,daterange(from_date,to_date,'[)') WITH &&));
CREATE TABLE accounting.bas_period_controls(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),state text NOT NULL DEFAULT 'OPEN' CHECK(state IN('OPEN','FINALIZED','LODGED')),version bigint NOT NULL DEFAULT 1,current_snapshot_id uuid,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,id) REFERENCES accounting.bas_periods(company_id,id));
CREATE TABLE accounting.bas_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),period_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),report jsonb NOT NULL,financial_hash text NOT NULL CHECK(financial_hash~'^[0-9a-f]{64}$'),source_hash text NOT NULL CHECK(source_hash~'^[0-9a-f]{64}$'),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,period_id,id),UNIQUE(company_id,period_id,revision),FOREIGN KEY(company_id,period_id) REFERENCES accounting.bas_periods(company_id,id));
ALTER TABLE accounting.bas_period_controls ADD FOREIGN KEY(company_id,id,current_snapshot_id) REFERENCES accounting.bas_snapshots(company_id,period_id,id);
CREATE TABLE accounting.bas_snapshot_items(company_id uuid NOT NULL REFERENCES core.companies(id),snapshot_id uuid NOT NULL,source_type text NOT NULL,source_id uuid NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(company_id,snapshot_id,source_type,source_id),FOREIGN KEY(company_id,snapshot_id) REFERENCES accounting.bas_snapshots(company_id,id));
CREATE TABLE accounting.bas_period_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),period_id uuid NOT NULL,snapshot_id uuid NOT NULL,action text NOT NULL CHECK(action IN('FINALIZED','REOPENED','LODGED')),reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),lodged_on date,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,action,reference),FOREIGN KEY(company_id,period_id,snapshot_id) REFERENCES accounting.bas_snapshots(company_id,period_id,id),CHECK((action='LODGED')=(lodged_on IS NOT NULL)));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bas_periods','bas_period_controls','bas_snapshots','bas_snapshot_items','bas_period_events'] LOOP EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company()) WITH CHECK(company_id=core.current_company())',t);IF t<>'bas_period_controls' THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END $$;
CREATE TRIGGER touch_version BEFORE UPDATE ON accounting.bas_period_controls FOR EACH ROW EXECUTE FUNCTION core.touch_version();
INSERT INTO identity.permissions(code,description) VALUES('accounting.bas.read','Read GST/BAS workpapers and filing periods'),('accounting.bas.manage','Create BAS periods'),('accounting.bas.finalize','Freeze internally reviewed BAS workpapers'),('accounting.bas.reopen','Reopen BAS with immutable earlier versions'),('accounting.bas.lodged','Record externally lodged BAS reference');
CREATE FUNCTION identity.seed_bas_roles(c uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN INSERT INTO identity.role_permissions(company_id,role_id,permission_code) SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE') AND p.code LIKE 'accounting.bas.%' ON CONFLICT DO NOTHING;END $$;
DO $$ DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_bas_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE FUNCTION accounting.bas_require_access(permission text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM purchase.require_access('accounting.bas.read');PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.gst.read');PERFORM purchase.require_access('purchase.input_gst.read');IF permission<>'accounting.bas.read' THEN PERFORM purchase.require_access(permission);END IF;END $$;
CREATE FUNCTION accounting.bas_lock(c uuid,exclusive_lock boolean) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF exclusive_lock THEN PERFORM pg_advisory_xact_lock(hashtextextended('bas-period:'||c::text,0));ELSE PERFORM pg_advisory_xact_lock_shared(hashtextextended('bas-period:'||c::text,0));END IF;END $$;
CREATE VIEW accounting.bas_tax_events WITH(security_invoker=true) AS
 SELECT g.company_id,'SALES_ATTRIBUTION'::text AS source_type,g.id AS source_id,g.source_document_id,'SALES'::text AS side,g.gst_basis,g.attribution_date,g.tax_code_id,g.kind,g.amount AS source_gross,g.gst_amount,g.gst_amount AS label_1a,0::numeric AS label_1b FROM accounting.gst_attributions g
 UNION ALL
 SELECT g.company_id,'SALES_ADJUSTMENT',g.id,g.source_document_id,'SALES',g.gst_basis,g.adjustment_date,g.tax_code_id,g.kind,g.amount,g.gst_amount,
 CASE WHEN g.kind IN('RECEIPT_REVERSAL','ADVANCE_UNAPPLICATION') THEN g.gst_amount WHEN g.kind='CUSTOMER_REFUND_REVERSAL' THEN 0 WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM sales.credit_unapplications u JOIN sales.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.target_invoice_line_id=g.invoice_line_id) THEN g.gst_amount ELSE 0 END ELSE greatest(g.gst_amount,0) END,
 CASE WHEN g.kind IN('RECEIPT_REVERSAL','ADVANCE_UNAPPLICATION') THEN 0 WHEN g.kind='CUSTOMER_REFUND_REVERSAL' THEN -g.gst_amount WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM sales.credit_unapplications u JOIN sales.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.source_invoice_line_id=g.invoice_line_id) THEN -g.gst_amount ELSE 0 END ELSE greatest(-g.gst_amount,0) END FROM accounting.gst_adjustments g
 UNION ALL
 SELECT g.company_id,'PURCHASE_INVOICE',g.id,l.bill_id,'PURCHASES',g.gst_basis,g.attribution_date,g.tax_code_id,'NON_CASH_BILL',l.net+l.tax,g.recoverable_tax,0,g.recoverable_tax FROM accounting.purchase_gst_entries g JOIN purchase.bill_lines l ON l.company_id=g.company_id AND l.id=g.bill_line_id WHERE g.gst_basis='NON_CASH' AND g.attribution_date IS NOT NULL
 UNION ALL
 SELECT g.company_id,'PURCHASE_ATTRIBUTION',g.id,g.source_document_id,'PURCHASES','CASH',g.attribution_date,e.tax_code_id,'CASH_PAYMENT',g.amount,g.gst_amount,0,g.gst_amount FROM accounting.purchase_gst_attributions g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id
 UNION ALL
 SELECT g.company_id,'PURCHASE_ADJUSTMENT',g.id,g.source_document_id,'PURCHASES',g.gst_basis,g.adjustment_date,e.tax_code_id,g.kind,g.amount,g.gst_amount,
 CASE WHEN g.kind IN('SUPPLIER_PAYMENT_REVERSAL','SUPPLIER_ADVANCE_UNAPPLICATION') THEN 0 WHEN g.kind='SUPPLIER_REFUND_REVERSAL' THEN -g.gst_amount WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM purchase.credit_unapplications u JOIN purchase.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.source_bill_line_id=g.bill_line_id) THEN -g.gst_amount ELSE 0 END ELSE greatest(-g.gst_amount,0) END,
 CASE WHEN g.kind IN('SUPPLIER_PAYMENT_REVERSAL','SUPPLIER_ADVANCE_UNAPPLICATION') THEN g.gst_amount WHEN g.kind='SUPPLIER_REFUND_REVERSAL' THEN 0 WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM purchase.credit_unapplications u JOIN purchase.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.target_bill_line_id=g.bill_line_id) THEN g.gst_amount ELSE 0 END ELSE greatest(g.gst_amount,0) END FROM accounting.purchase_gst_adjustments g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id;
CREATE VIEW accounting.bas_tax_roles WITH(security_invoker=true) AS
 SELECT company_id,output_account_id AS account_id,'OUTPUT'::text AS role FROM accounting.tax_account_mappings
 UNION SELECT company_id,input_account_id,'INPUT' FROM accounting.tax_account_mappings
 UNION SELECT company_id,output_account_id,'OUTPUT' FROM accounting.sales_gst_entries WHERE output_account_id IS NOT NULL
 UNION SELECT company_id,output_account_id,'OUTPUT' FROM accounting.customer_advances WHERE output_account_id IS NOT NULL
 UNION SELECT company_id,input_account_id,'INPUT' FROM accounting.purchase_gst_entries WHERE input_account_id IS NOT NULL
 UNION SELECT company_id,debit_account_id,'INPUT_DEFERRED' FROM accounting.purchase_gst_entries WHERE gst_basis='CASH' AND recoverable_tax>0
 UNION SELECT company_id,clearing_account_id,'ADVANCE_CLEARING' FROM accounting.customer_advances
 UNION SELECT company_id,account_id,CASE WHEN purpose='GST_ADVANCE_CLEARING' THEN 'ADVANCE_CLEARING' ELSE 'INPUT_DEFERRED' END FROM accounting.account_mappings WHERE purpose IN('GST_ADVANCE_CLEARING','GST_INPUT_DEFERRED');
CREATE VIEW accounting.bas_expected_gl WITH(security_invoker=true) AS
SELECT g.company_id AS company_id,g.output_account_id AS account_id,l.invoice_id AS source_document_id,i.invoice_date AS posting_date,-g.tax AS debit_signed FROM accounting.sales_gst_entries g JOIN sales.invoice_lines l ON l.company_id=g.company_id AND l.id=g.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id
UNION ALL
SELECT l.company_id AS company_id,g.output_account_id AS account_id,l.credit_note_id AS source_document_id,d.business_date AS posting_date,l.tax AS debit_signed FROM sales.credit_note_lines l JOIN accounting.sales_gst_entries g ON g.company_id=l.company_id AND g.invoice_line_id=l.invoice_line_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.credit_note_id
UNION ALL
SELECT a.company_id AS company_id,a.output_account_id AS account_id,a.receipt_id AS source_document_id,r.received_on AS posting_date,-a.gst_amount AS debit_signed FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id
UNION ALL
SELECT a.company_id AS company_id,a.clearing_account_id AS account_id,a.receipt_id AS source_document_id,r.received_on AS posting_date,a.gst_amount AS debit_signed FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id
UNION ALL
SELECT c.company_id AS company_id,g.output_account_id AS account_id,l.invoice_id AS source_document_id,i.invoice_date AS posting_date,c.gst_amount AS debit_signed FROM accounting.advance_gst_clearings c JOIN accounting.customer_advances a ON a.company_id=c.company_id AND a.id=c.advance_id JOIN sales.invoice_lines l ON l.company_id=c.company_id AND l.id=c.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN accounting.sales_gst_entries g ON g.company_id=l.company_id AND g.invoice_line_id=l.id
UNION ALL
SELECT c.company_id AS company_id,a.clearing_account_id AS account_id,l.invoice_id AS source_document_id,i.invoice_date AS posting_date,-c.gst_amount AS debit_signed FROM accounting.advance_gst_clearings c JOIN accounting.customer_advances a ON a.company_id=c.company_id AND a.id=c.advance_id JOIN sales.invoice_lines l ON l.company_id=c.company_id AND l.id=c.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN accounting.sales_gst_entries g ON g.company_id=l.company_id AND g.invoice_line_id=l.id
UNION ALL
SELECT ap.company_id AS company_id,a.output_account_id AS account_id,ap.id AS source_document_id,d.business_date AS posting_date,t.tax AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT ap.company_id AS company_id,a.clearing_account_id AS account_id,ap.id AS source_document_id,d.business_date AS posting_date,-t.tax AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT ap.company_id AS company_id,a.output_account_id AS account_id,ap.id AS source_document_id,coalesce((SELECT min(attribution_date) FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_TRANSFER'),r.received_on) AS posting_date,-(t.tax-ap.consumed_gst) AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT ap.company_id AS company_id,a.clearing_account_id AS account_id,ap.id AS source_document_id,coalesce((SELECT min(attribution_date) FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_TRANSFER'),r.received_on) AS posting_date,t.tax-ap.consumed_gst AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT g.company_id AS company_id,a.output_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,-g.gst_amount AS debit_signed FROM accounting.gst_adjustments g JOIN accounting.customer_advances a ON a.company_id=g.company_id AND a.id=g.advance_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,a.clearing_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,g.gst_amount AS debit_signed FROM accounting.gst_adjustments g JOIN accounting.customer_advances a ON a.company_id=g.company_id AND a.id=g.advance_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,g.debit_account_id AS account_id,l.bill_id AS source_document_id,d.business_date AS posting_date,g.recoverable_tax AS debit_signed FROM accounting.purchase_gst_entries g JOIN purchase.bill_lines l ON l.company_id=g.company_id AND l.id=g.bill_line_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.bill_id
UNION ALL
SELECT l.company_id AS company_id,g.debit_account_id AS account_id,l.credit_note_id AS source_document_id,d.business_date AS posting_date,-l.recoverable_tax AS debit_signed FROM purchase.supplier_credit_lines l JOIN accounting.purchase_gst_entries g ON g.company_id=l.company_id AND g.bill_line_id=l.bill_line_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.credit_note_id
UNION ALL
SELECT g.company_id AS company_id,g.input_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,g.gst_amount AS debit_signed FROM accounting.purchase_gst_attributions g JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,g.deferred_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,-g.gst_amount AS debit_signed FROM accounting.purchase_gst_attributions g JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,e.input_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,g.gst_amount AS debit_signed FROM accounting.purchase_gst_adjustments g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id WHERE g.gst_basis='CASH'
UNION ALL
SELECT g.company_id AS company_id,e.debit_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,-g.gst_amount AS debit_signed FROM accounting.purchase_gst_adjustments g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id WHERE g.gst_basis='CASH';
CREATE VIEW accounting.bas_cash_sales WITH(security_invoker=true) AS
SELECT x.company_id,'CASH_INVOICE_RECEIPT'::text AS source_type,x.id AS source_id,x.source_document_id AS source_document_id,r.received_on AS event_date,l.tax_code_id AS tax_code_id,x.amount AS gross_amount FROM accounting.payment_allocations x JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN accounting.customer_receipts r ON r.company_id=x.company_id AND r.id=x.receipt_id WHERE x.advance_id IS NULL AND i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_RECEIPT'::text AS source_type,x.id AS source_id,x.receipt_id AS source_document_id,r.received_on AS event_date,x.tax_code_id AS tax_code_id,x.amount AS gross_amount FROM accounting.customer_advances x JOIN accounting.customer_receipts r ON r.company_id=x.company_id AND r.id=x.receipt_id JOIN core.companies c ON c.id=x.company_id WHERE x.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_INVOICE_RECEIPT_REVERSAL'::text AS source_type,a.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-a.amount AS gross_amount FROM accounting.receipt_reversals x JOIN accounting.payment_allocations a ON a.company_id=x.company_id AND a.receipt_id=x.receipt_id AND a.advance_id IS NULL JOIN sales.invoice_lines l ON l.company_id=a.company_id AND l.id=a.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_RECEIPT_REVERSAL'::text AS source_type,a.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,a.tax_code_id AS tax_code_id,-a.amount AS gross_amount FROM accounting.receipt_reversals x JOIN accounting.customer_advances a ON a.company_id=x.company_id AND a.receipt_id=x.receipt_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN core.companies c ON c.id=x.company_id WHERE a.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_CREDIT_REFUND'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-x.amount AS gross_amount FROM accounting.customer_refunds x JOIN sales.credit_note_lines cl ON cl.company_id=x.company_id AND cl.id=x.credit_line_id JOIN sales.invoice_lines l ON l.company_id=cl.company_id AND l.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_REFUND'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,a.tax_code_id AS tax_code_id,-x.amount AS gross_amount FROM accounting.customer_refunds x JOIN accounting.customer_advances a ON a.company_id=x.company_id AND a.id=x.advance_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN core.companies c ON c.id=x.company_id WHERE a.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_CREDIT_REFUND_REVERSAL'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,rf.amount AS gross_amount FROM accounting.customer_refund_reversals x JOIN accounting.customer_refunds rf ON rf.company_id=x.company_id AND rf.id=x.refund_id JOIN sales.credit_note_lines cl ON cl.company_id=rf.company_id AND cl.id=rf.credit_line_id JOIN sales.invoice_lines l ON l.company_id=cl.company_id AND l.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_REFUND_REVERSAL'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,a.tax_code_id AS tax_code_id,rf.amount AS gross_amount FROM accounting.customer_refund_reversals x JOIN accounting.customer_refunds rf ON rf.company_id=x.company_id AND rf.id=x.refund_id JOIN accounting.customer_advances a ON a.company_id=rf.company_id AND a.id=rf.advance_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN core.companies c ON c.id=x.company_id WHERE a.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_CREDIT_APPLICATION_SOURCE'::text AS source_type,x.id AS source_id,x.application_id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-1*x.amount AS gross_amount FROM sales.credit_application_lines x JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.source_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.application_id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_CREDIT_APPLICATION_TARGET'::text AS source_type,x.id AS source_id,x.application_id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,1*x.amount AS gross_amount FROM sales.credit_application_lines x JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.target_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.application_id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_CREDIT_UNAPPLICATION_SOURCE'::text AS source_type,x.id AS source_id,u.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,1*x.amount AS gross_amount FROM sales.credit_unapplications u JOIN sales.credit_application_lines x ON x.company_id=u.company_id AND x.application_id=u.application_id JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.source_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=u.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_CREDIT_UNAPPLICATION_TARGET'::text AS source_type,x.id AS source_id,u.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-1*x.amount AS gross_amount FROM sales.credit_unapplications u JOIN sales.credit_application_lines x ON x.company_id=u.company_id AND x.application_id=u.application_id JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.target_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=u.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false);
CREATE FUNCTION accounting.bas_non_cash_positions(on_date date) RETURNS TABLE(company_id uuid,source_type text,source_id uuid,source_document_id uuid,tax_code_id uuid,gross_amount numeric) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH invoice_totals AS MATERIALIZED(SELECT l.order_line_id,sum(l.gross) AS billed_all,coalesce(sum(l.gross)FILTER(WHERE i.gst_basis='NON_CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)),0) AS billed_nc FROM sales.invoice_lines l JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id WHERE l.company_id=core.current_company() AND i.invoice_date<=on_date GROUP BY l.order_line_id),
 triggered AS MATERIALIZED(SELECT DISTINCT a.order_line_id FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN core.companies c ON c.id=a.company_id WHERE a.company_id=core.current_company() AND a.gst_basis='NON_CASH' AND c.gst_registered AND r.received_on<=on_date AND NOT EXISTS(SELECT 1 FROM accounting.receipt_reversals v JOIN platform.documents d ON d.company_id=v.company_id AND d.id=v.id WHERE v.company_id=a.company_id AND v.receipt_id=r.id AND d.business_date<=on_date)),
 cancelled AS MATERIALIZED(SELECT l.order_line_id,sum(l.cancelled_gross) AS amount FROM inventory.sales_return_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.return_id WHERE l.company_id=core.current_company() AND l.invoice_line_id IS NULL AND d.business_date<=on_date GROUP BY l.order_line_id),
 credited AS MATERIALIZED(SELECT il.order_line_id,sum(cl.gross) AS amount FROM sales.credit_note_lines cl JOIN sales.invoice_lines il ON il.company_id=cl.company_id AND il.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id JOIN platform.documents d ON d.company_id=cl.company_id AND d.id=cl.credit_note_id WHERE cl.company_id=core.current_company() AND i.gst_basis='NON_CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false) AND d.business_date<=on_date GROUP BY il.order_line_id)
 SELECT l.company_id,'NON_CASH_ORDER'::text,l.id,l.order_id,coalesce((SELECT il.tax_code_id FROM sales.invoice_lines il WHERE il.company_id=l.company_id AND il.order_line_id=l.id ORDER BY il.id LIMIT 1),(SELECT a.tax_code_id FROM accounting.customer_advances a WHERE a.company_id=l.company_id AND a.order_line_id=l.id ORDER BY a.id LIMIT 1),tc.id),
 coalesce(i.billed_nc,0)+CASE WHEN tr.order_line_id IS NOT NULL AND(o.cancelled_at IS NULL OR (o.cancelled_at AT TIME ZONE c.timezone)::date>on_date) THEN greatest(0,l.gross-coalesce(i.billed_all,0)-coalesce(ca.amount,0)) ELSE 0 END-coalesce(cr.amount,0)
 FROM sales.order_lines l JOIN sales.orders o ON o.company_id=l.company_id AND o.id=l.order_id JOIN core.companies c ON c.id=l.company_id LEFT JOIN invoice_totals i ON i.order_line_id=l.id LEFT JOIN triggered tr ON tr.order_line_id=l.id LEFT JOIN cancelled ca ON ca.order_line_id=l.id LEFT JOIN credited cr ON cr.order_line_id=l.id LEFT JOIN accounting.tax_codes tc ON tc.company_id=l.company_id AND tc.code=l.snapshot->>'taxCode' WHERE l.company_id=core.current_company() AND(i.order_line_id IS NOT NULL OR tr.order_line_id IS NOT NULL OR cr.order_line_id IS NOT NULL)
 $$;
CREATE FUNCTION accounting.bas_turnover(p_from date,p_to date) RETURNS TABLE(company_id uuid,source_type text,source_id uuid,source_document_id uuid,gst_basis text,event_date date,tax_code_id uuid,gross_amount numeric) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH opening AS MATERIALIZED(SELECT * FROM accounting.bas_non_cash_positions(p_from-1)),closing AS MATERIALIZED(SELECT * FROM accounting.bas_non_cash_positions(p_to-1))
 SELECT x.company_id,x.source_type,x.source_id,x.source_document_id,'CASH',x.event_date,x.tax_code_id,x.gross_amount FROM accounting.bas_cash_sales x WHERE x.company_id=core.current_company() AND x.event_date>=p_from AND x.event_date<p_to
 UNION ALL SELECT coalesce(c.company_id,o.company_id),'NON_CASH_ORDER_CHANGE',coalesce(c.source_id,o.source_id),coalesce(c.source_document_id,o.source_document_id),'NON_CASH',p_to-1,coalesce(c.tax_code_id,o.tax_code_id),coalesce(c.gross_amount,0)-coalesce(o.gross_amount,0) FROM closing c FULL JOIN opening o ON o.company_id=c.company_id AND o.source_id=c.source_id WHERE coalesce(c.gross_amount,0)<>coalesce(o.gross_amount,0)
 $$;

CREATE FUNCTION accounting.bas_source_items(p_from date,p_to date) RETURNS TABLE(source_type text,source_id uuid,payload jsonb) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT 'TAX_'||e.source_type,e.source_id,to_jsonb(e)||jsonb_build_object('source_gross',e.source_gross::text,'gst_amount',e.gst_amount::text,'label_1a',e.label_1a::text,'label_1b',e.label_1b::text) FROM accounting.bas_tax_events e WHERE e.company_id=core.current_company() AND e.attribution_date>=p_from AND e.attribution_date<p_to
 UNION ALL SELECT 'GROSS_'||e.source_type,e.source_id,to_jsonb(e)||jsonb_build_object('gross_amount',e.gross_amount::text,'includedInG1',coalesce(t.category<>'OUT_OF_SCOPE',false)) FROM accounting.bas_turnover(p_from,p_to)e LEFT JOIN accounting.tax_codes t ON t.company_id=e.company_id AND t.id=e.tax_code_id
 $$;
CREATE FUNCTION accounting.bas_summary(p_from date,p_to date) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH tax AS MATERIALIZED(SELECT * FROM accounting.bas_tax_events WHERE company_id=core.current_company() AND attribution_date>=p_from AND attribution_date<p_to),
 gross AS MATERIALIZED(SELECT g.*,t.category FROM accounting.bas_turnover(p_from,p_to)g LEFT JOIN accounting.tax_codes t ON t.company_id=g.company_id AND t.id=g.tax_code_id),
 roles AS MATERIALIZED(SELECT a.id,a.code,a.name,coalesce(string_agg(DISTINCT r.role,',' ORDER BY r.role),'OTHER') AS role,count(DISTINCT r.role) AS role_count FROM accounting.accounts a LEFT JOIN accounting.bas_tax_roles r ON r.company_id=a.company_id AND r.account_id=a.id WHERE a.company_id=core.current_company() AND(a.control_kind='GST' OR r.account_id IS NOT NULL) GROUP BY a.id),
 expected AS MATERIALIZED(SELECT account_id,coalesce(sum(debit_signed)FILTER(WHERE posting_date<p_from),0) AS opening,coalesce(sum(debit_signed)FILTER(WHERE posting_date>=p_from),0) AS movement FROM accounting.bas_expected_gl WHERE company_id=core.current_company() AND posting_date<p_to GROUP BY account_id),
 actual AS MATERIALIZED(SELECT l.account_id,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<p_from),0) AS opening,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date>=p_from),0) AS movement FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN roles r ON r.id=l.account_id WHERE l.company_id=core.current_company() AND j.posting_date<p_to GROUP BY l.account_id),
 accounts AS MATERIALIZED(SELECT r.*,coalesce(e.opening,0) AS expected_opening,coalesce(e.movement,0) AS expected_movement,coalesce(a.opening,0) AS actual_opening,coalesce(a.movement,0) AS actual_movement FROM roles r LEFT JOIN expected e ON e.account_id=r.id LEFT JOIN actual a ON a.account_id=r.id),
 totals AS(SELECT coalesce((SELECT sum(gross_amount) FROM gross WHERE category<>'OUT_OF_SCOPE'),0) AS g1,coalesce(sum(label_1a),0) AS a1,coalesce(sum(label_1b),0) AS b1,coalesce(sum(gst_amount)FILTER(WHERE side='SALES'),0) AS sales_tax,coalesce(sum(gst_amount)FILTER(WHERE side='PURCHASES'),0) AS purchase_tax FROM tax),
 issues AS(SELECT (SELECT count(*) FROM accounts WHERE expected_opening<>actual_opening OR expected_movement<>actual_movement) AS gl_errors,(SELECT count(*) FROM accounts WHERE role_count>1 OR(role='OTHER' AND(actual_opening<>0 OR actual_movement<>0))) AS role_errors,(SELECT count(*) FROM gross WHERE tax_code_id IS NULL OR category IS NULL) AS code_errors,(SELECT count(*) FROM expected e WHERE NOT EXISTS(SELECT 1 FROM roles r WHERE r.id=e.account_id) AND(e.opening<>0 OR e.movement<>0)) AS missing_accounts),
 bridge AS(SELECT coalesce(sum(-actual_movement)FILTER(WHERE role='OUTPUT'),0)-coalesce(sum(actual_movement)FILTER(WHERE role='INPUT'),0) AS book_net,coalesce(sum(-expected_movement)FILTER(WHERE role='OUTPUT'),0)-coalesce(sum(expected_movement)FILTER(WHERE role='INPUT'),0) AS expected_book_net FROM accounts),
 financial AS(SELECT jsonb_build_object('G1',g1::text,'1A',a1::text,'1B',b1::text,'netGst',(a1-b1)::text,'sourceSalesTax',sales_tax::text,'sourcePurchaseTax',purchase_tax::text,'bookNet',book_net::text,'timingAndCashBasisBridge',(expected_book_net-sales_tax+purchase_tax)::text,'unreconciledDifference',(book_net-expected_book_net)::text,'labelDifference',(a1-b1-sales_tax+purchase_tax)::text,
 'glErrorCount',gl_errors,'roleErrorCount',role_errors,'missingTaxCodeCount',code_errors,'missingAccountCount',missing_accounts,
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('accountId',id,'role',role,'expectedOpening',expected_opening::text,'actualOpening',actual_opening::text,'expectedMovement',expected_movement::text,'actualMovement',actual_movement::text,'expectedClosing',(expected_opening+expected_movement)::text,'actualClosing',(actual_opening+actual_movement)::text,'openingDifference',(actual_opening-expected_opening)::text,'movementDifference',(actual_movement-expected_movement)::text)ORDER BY id) FROM accounts WHERE expected_opening<>0 OR expected_movement<>0 OR actual_opening<>0 OR actual_movement<>0),'[]'::jsonb)) AS value,
 CASE WHEN gl_errors+role_errors+code_errors+missing_accounts>0 OR a1-b1<>sales_tax-purchase_tax THEN 'UNRECONCILED' WHEN g1<0 OR a1<0 OR b1<0 THEN 'REVIEW_REQUIRED' ELSE 'READY' END AS status FROM totals CROSS JOIN issues CROSS JOIN bridge)
 SELECT jsonb_build_object('companyId',core.current_company(),'currency','AUD','method','ACCOUNTS_SIMPLER','gstInclusive',true,'from',p_from,'to',p_to,'snapshotAt',statement_timestamp(),'status',f.status,'ledgerStatus',CASE WHEN (f.value->>'glErrorCount')::bigint+(f.value->>'roleErrorCount')::bigint+(f.value->>'missingAccountCount')::bigint=0 THEN 'RECONCILED' ELSE 'UNRECONCILED' END,'financial',f.value,
 'wholeDollarLabels',jsonb_build_object('G1',trunc(t.g1)::text,'1A',trunc(t.a1)::text,'1B',trunc(t.b1)::text,'netGst',(trunc(t.a1)-trunc(t.b1))::text,'roundingDifference',(trunc(t.a1)-trunc(t.b1)-t.a1+t.b1)::text),
 'basisBreakdown',coalesce((SELECT jsonb_agg(jsonb_build_object('basis',b.gst_basis,'sourceSalesTax',b.sales_tax::text,'sourcePurchaseTax',b.purchase_tax::text)ORDER BY gst_basis) FROM(SELECT gst_basis,coalesce(sum(gst_amount)FILTER(WHERE side='SALES'),0)AS sales_tax,coalesce(sum(gst_amount)FILTER(WHERE side='PURCHASES'),0)AS purchase_tax FROM tax GROUP BY gst_basis)b),'[]'::jsonb),
 'taxSourceCount',(SELECT count(*) FROM tax),'grossSourceCount',(SELECT count(*) FROM gross)) FROM financial f CROSS JOIN totals t
 $$;
-- Financial fingerprints compare numeric value, not PostgreSQL's incidental decimal display scale.
CREATE FUNCTION accounting.bas_canonical_json(value jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE result jsonb;BEGIN
 IF jsonb_typeof(value)='object' THEN SELECT coalesce(jsonb_object_agg(key,accounting.bas_canonical_json(v)),'{}'::jsonb) INTO result FROM jsonb_each(value) AS x(key,v);RETURN result;
 ELSIF jsonb_typeof(value)='array' THEN SELECT coalesce(jsonb_agg(accounting.bas_canonical_json(v) ORDER BY n),'[]'::jsonb) INTO result FROM jsonb_array_elements(value) WITH ORDINALITY AS x(v,n);RETURN result;
 ELSIF jsonb_typeof(value)='string' AND (value#>>'{}')~'^-?[0-9]+([.][0-9]+)?$' THEN RETURN to_jsonb(trim_scale((value#>>'{}')::numeric)::text);END IF;RETURN value;END $$;
CREATE FUNCTION accounting.bas_financial_hash(report jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(accounting.bas_canonical_json(report->'financial')::text,'UTF8')),'hex') $$;
CREATE FUNCTION accounting.create_bas_period(p_reference text,p_from date,p_to date,p_cadence text,p_basis text,p_method text,p_registered boolean,p_due date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();v uuid:=gen_random_uuid();BEGIN
 PERFORM accounting.bas_require_access('accounting.bas.manage');PERFORM accounting.bas_lock(c,true);
 IF p_from IS NULL OR p_to IS NULL OR p_from<'0002-01-01' OR p_to<=p_from OR p_to-p_from>366 OR p_registered IS DISTINCT FROM true OR p_method IS DISTINCT FROM 'SIMPLER' OR p_basis NOT IN('CASH','NON_CASH') OR p_basis IS NULL OR p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_due<p_to THEN RAISE EXCEPTION 'Invalid BAS period or explicit registration/method confirmation missing' USING ERRCODE='HR422';END IF;
 IF p_cadence IS NULL OR p_cadence NOT IN('MONTHLY','QUARTERLY','ANNUAL','CUSTOM') OR(p_cadence<>'CUSTOM' AND(extract(day FROM p_from)<>1 OR(p_cadence='MONTHLY' AND p_to<>(p_from+interval '1 month')::date) OR(p_cadence='QUARTERLY' AND(extract(month FROM p_from)::int NOT IN(1,4,7,10) OR p_to<>(p_from+interval '3 month')::date)) OR(p_cadence='ANNUAL' AND(extract(month FROM p_from)<>7 OR p_to<>(p_from+interval '1 year')::date)))) THEN RAISE EXCEPTION 'Invalid BAS cadence' USING ERRCODE='HR422';END IF;
 IF NOT EXISTS(SELECT 1 FROM core.companies WHERE id=c AND abn IS NOT NULL AND length(abn)=11) THEN RAISE EXCEPTION 'Company ABN required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bas_periods WHERE company_id=c AND from_date<p_to AND to_date>p_from) THEN RAISE EXCEPTION 'BAS periods overlap' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.bas_periods(id,company_id,reference,from_date,to_date,cadence,gst_basis,reporting_method,registration_confirmed,due_on,created_by) VALUES(v,c,btrim(p_reference),p_from,p_to,p_cadence,p_basis,p_method,true,p_due,core.current_actor());
 INSERT INTO accounting.bas_period_controls(id,company_id) VALUES(v,c);RETURN v;END $$;
CREATE FUNCTION accounting.bas_transition(p_id uuid,p_version bigint,p_action text,p_reference text,p_reason text,p_lodged date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();p accounting.bas_periods;k accounting.bas_period_controls;s uuid;report jsonb;rev bigint;today date;BEGIN
 IF p_action NOT IN('FINALIZED','REOPENED','LODGED') OR p_action IS NULL THEN RAISE EXCEPTION 'Invalid BAS action' USING ERRCODE='HR422';END IF;
 PERFORM accounting.bas_require_access(CASE p_action WHEN 'FINALIZED' THEN 'accounting.bas.finalize' WHEN 'REOPENED' THEN 'accounting.bas.reopen' ELSE 'accounting.bas.lodged' END);PERFORM accounting.bas_lock(c,true);
 SELECT * INTO p FROM accounting.bas_periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'BAS period unavailable' USING ERRCODE='HT404';END IF;
 SELECT * INTO k FROM accounting.bas_period_controls WHERE company_id=c AND id=p_id FOR UPDATE;IF k.version<>p_version OR p_version IS NULL THEN RAISE EXCEPTION 'BAS version changed' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reference and reason required' USING ERRCODE='HR422';END IF;
 SELECT (now() AT TIME ZONE timezone)::date INTO today FROM core.companies WHERE id=c;
 s:=k.current_snapshot_id;
 IF p_action='FINALIZED' THEN
 IF k.state<>'OPEN' THEN RAISE EXCEPTION 'BAS period is not open' USING ERRCODE='HR409';END IF;
 IF p.to_date>today+1 THEN RAISE EXCEPTION 'Future BAS period cannot be finalized' USING ERRCODE='HR422';END IF;
 report:=accounting.bas_summary(p.from_date,p.to_date)||jsonb_build_object('periodId',p.id,'declaredBasis',p.gst_basis,'registrationConfirmed',p.registration_confirmed,'amendsSnapshotId',(SELECT e.snapshot_id FROM accounting.bas_period_events e WHERE e.company_id=c AND e.period_id=p.id AND e.action='LODGED' ORDER BY e.created_at DESC,e.id DESC LIMIT 1));IF report->>'status'<>'READY' THEN RAISE EXCEPTION 'BAS requires financial review or ledger reconciliation' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(revision),0)+1 INTO rev FROM accounting.bas_snapshots WHERE company_id=c AND period_id=p_id;
 s:=gen_random_uuid();
 INSERT INTO accounting.bas_snapshots(id,company_id,period_id,revision,report,financial_hash,source_hash,reason,created_by) SELECT s,c,p_id,rev,report,accounting.bas_financial_hash(report),encode(sha256(convert_to(coalesce(string_agg(source_type||source_id::text||payload::text,'|' ORDER BY source_type,source_id),''),'UTF8')),'hex'),btrim(p_reason),core.current_actor() FROM accounting.bas_source_items(p.from_date,p.to_date);
 INSERT INTO accounting.bas_snapshot_items SELECT c,s,source_type,source_id,payload FROM accounting.bas_source_items(p.from_date,p.to_date);
 ELSIF p_action='REOPENED' THEN
 IF k.state NOT IN('FINALIZED','LODGED') THEN RAISE EXCEPTION 'BAS period is already open' USING ERRCODE='HR409';END IF;
 ELSE
 IF k.state<>'FINALIZED' THEN RAISE EXCEPTION 'Finalize BAS before recording lodgement' USING ERRCODE='HR409';END IF;
 IF p_lodged IS NULL OR p_lodged<p.to_date-1 OR p_lodged>today THEN RAISE EXCEPTION 'Invalid lodgement date' USING ERRCODE='HR422';END IF;
 END IF;
 INSERT INTO accounting.bas_period_events(company_id,period_id,snapshot_id,action,reference,reason,lodged_on,created_by) VALUES(c,p_id,s,p_action,btrim(p_reference),btrim(p_reason),CASE WHEN p_action='LODGED' THEN p_lodged END,core.current_actor());
 UPDATE accounting.bas_period_controls SET state=CASE p_action WHEN 'REOPENED' THEN 'OPEN' ELSE p_action END,current_snapshot_id=s WHERE company_id=c AND id=p_id;RETURN s;END $$;
-- Writers share a company lock with each other; finalization/reopening take it exclusively.
-- Deferred comparison permits balanced retroactive source redistribution but rejects any financial change to a frozen return.
CREATE FUNCTION accounting.bas_dirty() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN PERFORM set_config('htt.bas_dirty',gen_random_uuid()::text,true);RETURN NULL;END $$;
CREATE FUNCTION accounting.bas_write_lock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid;BEGIN c:=CASE WHEN TG_TABLE_SCHEMA='core' AND TG_TABLE_NAME='companies' THEN coalesce(NEW.id,OLD.id) ELSE coalesce((to_jsonb(NEW)->>'company_id')::uuid,(to_jsonb(OLD)->>'company_id')::uuid) END;PERFORM accounting.bas_lock(c,false);RETURN coalesce(NEW,OLD);END $$;
CREATE FUNCTION accounting.bas_check_frozen() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid;p record;token text;cache text;BEGIN
 c:=CASE WHEN TG_TABLE_SCHEMA='core' AND TG_TABLE_NAME='companies' THEN coalesce(NEW.id,OLD.id) ELSE coalesce((to_jsonb(NEW)->>'company_id')::uuid,(to_jsonb(OLD)->>'company_id')::uuid) END;
 IF c IS DISTINCT FROM core.current_company() THEN RAISE EXCEPTION 'BAS company context mismatch' USING ERRCODE='HR409';END IF;
 token:=coalesce(current_setting('htt.bas_dirty',true),'');cache:='htt.bas_checked_'||replace(c::text,'-','');IF current_setting(cache,true)=token THEN RETURN NULL;END IF;
 FOR p IN SELECT b.from_date,b.to_date,s.financial_hash FROM accounting.bas_period_controls k JOIN accounting.bas_periods b ON b.company_id=k.company_id AND b.id=k.id JOIN accounting.bas_snapshots s ON s.company_id=k.company_id AND s.id=k.current_snapshot_id WHERE k.company_id=c AND k.state IN('FINALIZED','LODGED') LOOP
 IF accounting.bas_financial_hash(accounting.bas_summary(p.from_date,p.to_date))<>p.financial_hash THEN RAISE EXCEPTION 'Reopen BAS period before changing frozen financial totals or tax ledger' USING ERRCODE='HR409';END IF;END LOOP;
 PERFORM set_config(cache,token,true);RETURN NULL;END $$;
