REVOKE ALL ON FUNCTION accounting.bas_require_access(text),accounting.create_bas_period(text,date,date,text,text,text,boolean,date),accounting.bas_transition(uuid,bigint,text,text,text,date),identity.seed_bas_roles(uuid),accounting.bas_check_frozen() FROM PUBLIC;
GRANT SELECT ON accounting.bas_periods,accounting.bas_period_controls,accounting.bas_snapshots,accounting.bas_snapshot_items,accounting.bas_period_events,accounting.bas_tax_events,accounting.bas_tax_roles,accounting.bas_expected_gl,accounting.bas_cash_sales TO htt_app;
GRANT EXECUTE ON FUNCTION accounting.create_bas_period(text,date,date,text,text,text,boolean,date),accounting.bas_transition(uuid,bigint,text,text,text,date) TO htt_app;

GRANT EXECUTE ON FUNCTION accounting.bas_summary(date,date),accounting.bas_source_items(date,date),accounting.bas_turnover(date,date),accounting.bas_non_cash_positions(date),accounting.bas_financial_hash(jsonb) TO htt_app;

GRANT EXECUTE ON FUNCTION accounting.bas_canonical_json(jsonb) TO htt_app;
